277			{"too old with commit suffix is refused", runnerReporting("Entire CLI 0.11.3 (abc1234)\n"), "0.12.0", true},
278			{"new enough with commit suffix passes", runnerReporting("Entire CLI 0.12.0 (abc1234)\n"), "0.12.0", false},
279			{"prerelease of the minimum passes", runnerReporting("Entire CLI 0.12.0-nightly.20261020\n"), "0.12.0", false},
280			{"pseudo-version above the minimum passes", runnerReporting("Entire CLI v0.12.1-0.20261020123456-abcdef123456\n"), "0.12.0", false},
281			{"prerelease of an older release is refused", runnerReporting("Entire CLI 0.11.3-nightly.1\n"), "0.12.0", true},
282			{"unset minimum disables the gate", runnerReporting("Entire CLI 0.11.3\n"), "", false},
283			{"minimum passes", runnerReporting("Entire CLI 0.12.0\n"), "0.12.0", false},
284			{"newer passes", runnerReporting("Entire CLI 0.13.1\n"), "0.12.0", false},
285			{"dev build passes", runnerReporting("Entire CLI dev\n"), "0.12.0", false},
286			{"missing CLI passes", commandRunnerFunc(func(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error) {
287				return nil, nil, errors.New("not found")
288			}), "0.12.0", false},
289		}
290		for _, tc := range cases {
291			err := checkHostCLIVersion(context.Background(), tc.runner, "/repo", tc.min)
292			if (err != nil) != tc.wantErr {
293				t.Errorf("%s: got err=%v, want error=%v", tc.name, err, tc.wantErr)
294			}
295		}
296	}
