11	// Backlog UX-21. About a hundred remedies hardcoded `entire brain <verb>`. On a
12	// plugin-style install the runnable spelling is the binary's own name, so each of
13	// them told the reader to type a command that does not exist for them. The
14	// guards below hold the fix from two directions: no source line may print the
15	// hardcoded spelling again (static, with a floor so it cannot match nothing),
16	// and the remedies that were converted must render in the spelling the
17	// environment dictates, in both modes (behavioural).
18	
19	// hardcodedBrainVerb is a literal "entire brain" followed by a verb this binary
20	// really has. Prose about the product ("entire brain viz — url") is not matched
21	// because it carries no verb from this list.
22	// Any verb, not an enumeration. The list used to name fifteen and the guard
23	// was then blind to every verb nobody remembered to add -- `reset` among them,
24	// which is how a hardcoded `entire brain reset` reached a printed remedy with
25	// this test passing. A new subcommand must not silently fall outside the rule.
26	var hardcodedBrainVerb = regexp.MustCompile(`entire brain [a-z][a-z-]*\b`)
27	
28	// deliberatelyHardcoded names the lines that keep the literal spelling, and why.
29	// Each reason is a category, not a per-line excuse.
30	var deliberatelyHardcoded = []struct{ file, contains, reason string }{
31		{"add.go", "with ` + \"`entire brain dash`\"", "cobra Long help text built at command-construction time, before any lookup exists"},
32		{"retrieve.go", `"entire brain search`, "matcher over transcript text, not a printed remedy"},
33		{"mcp.go", "entire brain", "MCP tool descriptions are pinned by TestMCPToolSurfaceGolden; env-dependent descriptions would make the golden vary by shell"},
34		{"seed.go", "Intake: run `entire brain inspect", "written into the persisted seed artifact; spelling must be deterministic, not reader-dependent"},
35		{"retrieve.go", `"entire brain query`, "matcher over transcript text, not a printed remedy"},
36		{"retrieve.go", `"entire brain brief`, "matcher over transcript text, not a printed remedy"},
37		{"viz.go", `"entire brain viz — %s`, "banner naming the surface being shown, not a command to run"},
38		{"publish.go", "(see 'entire brain connect')", "cobra Long help text built at command-construction time, before any lookup exists"},
39		{"disconnect_cmd.go", "'entire brain connect'", "cobra Long help text built at command-construction time, before any lookup exists"},
40		{"doctor.go", "cd '<your repository>' && entire brain doctor", "a shell TEMPLATE with a cd and a placeholder, not a verb the lookup can render"},
41	}
