43	func TestNoHardcodedBrainSpellingInPrintedRemedies(t *testing.T) {
44		entries, err := os.ReadDir(".")
45		if err != nil {
46			t.Fatal(err)
47		}
48		scanned, helperSites, allowed := 0, 0, 0
49		for _, entry := range entries {
50			name := entry.Name()
51			if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") || name == "setup_invocation.go" {
52				continue
53			}
54			data, err := os.ReadFile(name)
55			if err != nil {
56				t.Fatal(err)
57			}
58			for number, line := range strings.Split(string(data), "\n") {
59				scanned++
60				helperSites += strings.Count(line, "BrainInvocation(")
61				trimmed := strings.TrimSpace(line)
62				if strings.HasPrefix(trimmed, "//") || !hardcodedBrainVerb.MatchString(line) {
63					continue
64				}
65				ok := false
66				for _, a := range deliberatelyHardcoded {
67					if a.file == name && strings.Contains(line, a.contains) {
68						ok = true
69						allowed++
70					}
71				}
72				if !ok {
73					t.Errorf("%s:%d hardcodes `entire brain <verb>`; render it with base.BrainInvocation(os.LookupEnv, verb) "+
74						"or add a reasoned entry to deliberatelyHardcoded: %s", name, number+1, trimmed)
75				}
76			}
77		}
78		// Non-vacuity: the converted sites, and the deliberate exceptions, must
79		// actually have been seen.
80		if scanned < 10000 {
81			t.Fatalf("scanned only %d lines; the walk is broken", scanned)
82		}
83		if helperSites < 90 {
84			t.Fatalf("found only %d BrainInvocation call sites; the scan is matching nothing", helperSites)
85		}
86		if allowed < len(deliberatelyHardcoded) {
87			t.Fatalf("only %d of %d allowlist entries matched a line; stale allowlist or broken matcher", allowed, len(deliberatelyHardcoded))
88		}
89	}
